mapper.select:
SELECT COALESCE(
  (
    SELECT enabled
    FROM notification_preference
    WHERE user_id = #{userId}
      AND type = #{type}
      AND channel = #{channel}
    LIMIT 1
  ),
  (
    SELECT enabled
    FROM notification_preference
    WHERE user_id = #{userId}
      AND type = '*'
      AND channel = #{channel}
    LIMIT 1
  ),
  TRUE
)
